1	const PROCESSING_FEE = 5;
2	
3	type ItemType = "sword" | "amulet" | "staff" | "potion" | "rune" | "moonstone";
4	
5	const BASE_PREMIUM_BY_TYPE: Record<ItemType, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	  moonstone: 25,
12	};
13	
14	const INSURANCE_VALUE_BY_TYPE: Record<ItemType, number> = {
15	  sword: 1000,
16	  amulet: 600,
17	  staff: 800,
18	  potion: 400,
19	  rune: 250,
20	  moonstone: 250,
21	};
22	
23	type Item = {
24	  type: ItemType;
25	  material?: string;
26	  enchantment?: number;
27	  cursed?: boolean;
28	};
29	
30	type QuoteStep = { op: "quote"; items: Item[] };
31	
32	type Damage = { itemType: ItemType; amount: number };
33	
34	type Incident = { cause: string; damages: Damage[] };
35	
36	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
37	
38	type Step = QuoteStep | ClaimStep;
39	
40	type Customer = { yearsWithMHPCO: number };
41	
42	type Scenario = { customer: Customer; steps: Step[] };
43	
44	type QuoteResult = { premium: number };
45	
46	type ClaimResult = { payout: number; remainingCap: number };
47	
48	type Result = QuoteResult | ClaimResult;
49	
50	// A policy created by a quote step, tracked so later claims can draw on its cap.
51	type Policy = { items: Item[]; remainingCap: number };
52	
53	const COMPONENT_BLOCK_SIZE = 3;
54	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
55	
56	const COMPONENT_TYPES: ReadonlySet<ItemType> = new Set(["rune", "moonstone"]);
57	
58	// A group holds every item of one type, so the group's type identifies all of them.
59	type SameTypeGroup = { type: ItemType; items: Item[] };
60	
61	const groupByType = (items: Item[]): SameTypeGroup[] => {
62	  const itemsByType = new Map<ItemType, Item[]>();
63	  for (const item of items) {
64	    itemsByType.set(item.type, [...(itemsByType.get(item.type) ?? []), item]);
65	  }
66	  return [...itemsByType].map(([type, grouped]) => ({ type, items: grouped }));
67	};
68	
69	const isComponentBlock = (group: SameTypeGroup): boolean =>
70	  COMPONENT_TYPES.has(group.type) &&
71	  group.items.length === COMPONENT_BLOCK_SIZE;
72	
73	// A guard states what every element must satisfy and how to describe an
74	// offender, so each rule reads as a rule rather than as a loop.
75	const rejectAny = <T>(
76	  values: T[],
77	  isAllowed: (value: T) => boolean,
78	  describeOffender: (value: T) => string,
79	): void => {
80	  const offender = values.find((value) => !isAllowed(value));
81	  if (offender !== undefined) {
82	    throw new Error(describeOffender(offender));
83	  }
84	};
85	
86	const isInsurable = (item: Item): boolean => item.type in BASE_PREMIUM_BY_TYPE;
87	
88	const rejectUninsurableItems = (items: Item[]): void =>
89	  rejectAny(
90	    items,
91	    isInsurable,
92	    (item) => `The MHPCO does not insure items of type "${item.type}"`,
93	  );
94	
95	const basePremiumFor = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
96	
97	const sumOf = <T>(values: T[], amountFor: (value: T) => number): number =>
98	  values.reduce((sum, value) => sum + amountFor(value), 0);
99	
100	const basePremiumForGroup = (group: SameTypeGroup): number =>
101	  isComponentBlock(group)
102	    ? COMPONENT_BLOCK_BASE_PREMIUM
103	    : sumOf(group.items, basePremiumFor);
104	
105	const totalBasePremium = (items: Item[]): number =>
106	  sumOf(groupByType(items), basePremiumForGroup);
107	
108	// A modifier is a signed rate applied to some base premium: a surcharge is
109	// positive, a discount negative. It only counts when its condition holds.
110	type Modifier = { rate: number; applies: boolean };
111	
112	const surcharge = (rate: number, applies: boolean): Modifier => ({
113	  rate,
114	  applies,
115	});
116	
117	const discount = (rate: number, applies: boolean): Modifier => ({
118	  rate: -rate,
119	  applies,
120	});
121	
122	const modifierAmount = (basePremium: number, modifier: Modifier): number =>
123	  modifier.applies ? basePremium * modifier.rate : 0;
124	
125	const totalModifierAmounts = (
126	  basePremium: number,
127	  modifiers: Modifier[],
128	): number =>
129	  sumOf(modifiers, (modifier) => modifierAmount(basePremium, modifier));
130	
131	const CURSE_SURCHARGE_RATE = 0.5;
132	const HIGH_ENCHANTMENT_LEVEL = 5;
133	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
134	
135	// An item without an enchantment counts as enchantment level 0.
136	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
137	
138	const isHighlyEnchanted = (item: Item): boolean =>
139	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
140	
141	// Item modifiers are rates on the item's own base premium.
142	const itemModifiersFor = (item: Item): Modifier[] => [
143	  surcharge(CURSE_SURCHARGE_RATE, item.cursed === true),
144	  surcharge(HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted(item)),
145	];
146	
147	const itemModifierTotalFor = (item: Item): number =>
148	  totalModifierAmounts(basePremiumFor(item), itemModifiersFor(item));
149	
150	const LOYALTY_YEARS = 2;
151	const LOYALTY_DISCOUNT_RATE = 0.2;
152	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
153	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
154	
155	const isLoyal = (customer: Customer): boolean =>
156	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
157	
158	// Policy modifiers are rates on the whole policy's base premium. Every quote's
159	// items count as a first insurance, whatever the customer's history.
160	const ALWAYS = true;
161	
162	const policyModifiersFor = (
163	  customer: Customer,
164	  isFollowUpContract: boolean,
165	): Modifier[] => [
166	  discount(LOYALTY_DISCOUNT_RATE, isLoyal(customer)),
167	  surcharge(FIRST_INSURANCE_SURCHARGE_RATE, ALWAYS),
168	  discount(FOLLOW_UP_DISCOUNT_RATE, isFollowUpContract),
169	];
170	
171	// The MHPCO rounds in its own favour: premiums up, payouts down.
172	const roundPremiumUpInMHPCOsFavour = (premium: number): number =>
173	  Math.ceil(premium);
174	
175	const quote = (
176	  items: Item[],
177	  customer: Customer,
178	  isFollowUpContract: boolean,
179	): QuoteResult => {
180	  rejectUninsurableItems(items);
181	  const basePremium = totalBasePremium(items);
182	  const itemModifiers = sumOf(items, itemModifierTotalFor);
183	  const policyModifiers = totalModifierAmounts(
184	    basePremium,
185	    policyModifiersFor(customer, isFollowUpContract),
186	  );
187	  return {
188	    premium: roundPremiumUpInMHPCOsFavour(
189	      basePremium + itemModifiers + policyModifiers + PROCESSING_FEE,
190	    ),
191	  };
192	};
193	
194	const DEDUCTIBLE_PER_DAMAGE = 100;
195	
196	const insuranceValueFor = (item: Item): number =>
197	  INSURANCE_VALUE_BY_TYPE[item.type];
198	
199	const CAP_MULTIPLE = 2;
200	
201	const capFor = (items: Item[]): number =>
202	  CAP_MULTIPLE * sumOf(items, insuranceValueFor);
203	
204	const HALF_REIMBURSED_ENCHANTMENT_LEVEL = 8;
205	const HALF_REIMBURSEMENT_RATE = 0.5;
206	const FULL_REIMBURSEMENT_RATE = 1;
207	
208	// Damage to a very highly enchanted item is only half reimbursed.
209	const reimbursementRateFor = (item: Item): number =>
210	  enchantmentLevelOf(item) >= HALF_REIMBURSED_ENCHANTMENT_LEVEL
211	    ? HALF_REIMBURSEMENT_RATE
212	    : FULL_REIMBURSEMENT_RATE;
213	
214	const payoutForDamage = (damage: Damage, item: Item): number =>
215	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE_PER_DAMAGE;
216	
217	const roundPayoutDownInMHPCOsFavour = (payout: number): number =>
218	  Math.floor(payout);
219	
220	// A damage entry paired with the insured item it was suffered by.
221	type DamagedItem = { damage: Damage; item: Item };
222	
223	const NOT_FOUND = -1;
224	
225	// Removes and returns the first item of that type, or reports that the policy
226	// has none left to claim against.
227	const takeInsuredItem = (unclaimed: Item[], itemType: ItemType): Item => {
228	  const index = unclaimed.findIndex(({ type }) => type === itemType);
229	  if (index === NOT_FOUND) {
230	    throw new Error(
231	      `The policy does not cover that many items of type "${itemType}"`,
232	    );
233	  }
234	  const [item] = unclaimed.splice(index, 1);
235	  return item;
236	};
237	
238	// Each damage entry is a separate damage to a separate insured item, so every
239	// entry consumes one of the policy's items of that type.
240	const matchDamagesToInsuredItems = (
241	  policy: Policy,
242	  damages: Damage[],
243	): DamagedItem[] => {
244	  const unclaimed = [...policy.items];
245	  return damages.map((damage) => ({
246	    damage,
247	    item: takeInsuredItem(unclaimed, damage.itemType),
248	  }));
249	};
250	
251	// A policy never pays out more than it has left of its cap.
252	const limitedToRemainingCap = (desiredPayout: number, policy: Policy): number =>
253	  Math.min(desiredPayout, policy.remainingCap);
254	
255	const desiredPayoutFor = (policy: Policy, incident: Incident): number =>
256	  roundPayoutDownInMHPCOsFavour(
257	    sumOf(
258	      matchDamagesToInsuredItems(policy, incident.damages),
259	      ({ damage, item }) => payoutForDamage(damage, item),
260	    ),
261	  );
262	
263	// Paying a claim draws the payout off the policy's cap for good.
264	const drawFromCap = (policy: Policy, payout: number): number => {
265	  policy.remainingCap -= payout;
266	  return policy.remainingCap;
267	};
268	
269	const isNonNegativeDamage = ({ amount }: Damage): boolean => amount >= 0;
270	
271	const rejectNegativeDamages = (damages: Damage[]): void =>
272	  rejectAny(
273	    damages,
274	    isNonNegativeDamage,
275	    ({ amount }) => `A damage cannot be negative, but was ${amount} G`,
276	  );
277	
278	const claim = (policy: Policy, incident: Incident): ClaimResult => {
279	  rejectNegativeDamages(incident.damages);
280	  const payout = limitedToRemainingCap(
281	    desiredPayoutFor(policy, incident),
282	    policy,
283	  );
284	  return { payout, remainingCap: drawFromCap(policy, payout) };
285	};
286	
287	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
288	
289	// A claim names its policy by the index of the quote step that created it, so
290	// only a step that was a quote can be claimed against.
291	const policyCreatedByStep = (
292	  policies: Map<number, Policy>,
293	  stepIndex: number,
294	): Policy => {
295	  const policy = policies.get(stepIndex);
296	  if (policy === undefined) {
297	    throw new Error(`No policy was created by step ${stepIndex}`);
298	  }
299	  return policy;
300	};
301	
302	// A step is a follow-up contract when the customer already holds one from an
303	// earlier step of this scenario, so every quote but the first.
304	export const runScenario = (scenario: Scenario): { results: Result[] } => {
305	  const policies = new Map<number, Policy>();
306	
307	  const resultOf = (step: Step, index: number): Result => {
308	    if (isQuoteStep(step)) {
309	      const premium = quote(step.items, scenario.customer, policies.size > 0);
310	      policies.set(index, {
311	        items: step.items,
312	        remainingCap: capFor(step.items),
313	      });
314	      return premium;
315	    }
316	    return claim(policyCreatedByStep(policies, step.policy), step.incident);
317	  };
318	
319	  return { results: scenario.steps.map(resultOf) };
320	};
