3	const readStdin = async (): Promise<string> => {
4	  const chunks: string[] = [];
5	  process.stdin.setEncoding("utf8");
6	  for await (const chunk of process.stdin) {
7	    chunks.push(chunk as string);
8	  }
9	  return chunks.join("");
10	};
11	
12	// The scenario arrives as untyped JSON on stdin; runScenario is what gives it
13	// meaning, so the parsed value is only ever handed straight to it.
14	const readScenario = async (): Promise<Parameters<typeof runScenario>[0]> =>
15	  JSON.parse(await readStdin());
16	
17	const writeResults = (results: ReturnType<typeof runScenario>): void => {
18	  process.stdout.write(JSON.stringify(results));
19	};
20	
21	const REJECTED_EXIT_CODE = 1;
22	
23	// The MHPCO rejects a whole scenario it cannot process: nothing is written to
24	// stdout, only a description of the objection to stderr.
25	const reject = (reason: unknown): void => {
26	  process.stderr.write(`${reason instanceof Error ? reason.message : reason}\n`);
27	  process.exitCode = REJECTED_EXIT_CODE;
28	};
29	
30	const main = async (): Promise<void> => {
31	  try {
32	    writeResults(runScenario(await readScenario()));
33	  } catch (reason) {
34	    reject(reason);
35	  }
36	};
37	
38	await main();
